    {
      "claim": "Open-source models are structurally uncontainable because fine-tuning allows users to strip away alignment constraints.",
      "targets": []
    },
    {
      "claim": "True innovation is predicated on a stable, secure society, not the unchecked proliferation of unaligned systems.",
      "targets": []
