  "key_assumptions": [
    {
      "assumption": "Model alignment is a fragile, software-dependent property that can be easily removed by end-users.",
      "if_wrong": "If alignment were an inherent, immutable feature of high-capability models, the risk of open-weight distribution would be significantly lower."
